document.addEventListener('click',e=>{const button=(e.target as HTMLElement).closest<HTMLButtonElement>('[data-action]');if(!button)return;void (async()=>{if(busy){notice('上一次操作尚未完成，请稍候');return;}busy=true;button.disabled=true;const errorBox=$('dialog').open?$('dialogError'):$('pageError');if(errorBox)errorBox.hidden=true;try{await act(button.dataset.action,button.dataset.id||'');}catch(e){if(button.dataset.action==='test'){testResults[modelId]='本次测试失败；请检查下方错误提示';if($('modelTestResult'))$('modelTestResult').textContent=testResults[modelId];}const box=$('dialog').open?$('dialogError'):$('pageError');if(box){box.hidden=false;box.textContent=e.name==='AbortError'?'请求超时或已取消，未自动重试':e.message||String(e);}notice(e.name==='AbortError'?'请求超时或已取消；未自动重试':e.message||String(e),8000);}finally{busy=false;button.disabled=false;}})();});
$('files').onchange=async()=>{if(busy){notice('请等待当前操作完成后重新导入');return;}busy=true;const files=Array.from<File>($('files').files),errors:string[]=[];let n=0,duplicates=0;try{for(let i=0;i<files.length;i++){const file=files[i];notice(`正在导入 ${i+1}/${files.length}：${file.name}`,30000);try{if(!file.size)throw Error('文件为空');if(file.size>512*1048576)throw Error('单个文件超过 512MB');const fingerprint=await fileFingerprint(file);for(const old of tracks.filter(t=>!t.fingerprint&&t.size===file.size)){const record=await db.get('blobs',old.id);if(record?.blob){old.fingerprint=await fileFingerprint(record.blob);await db.put('tracks',old);if(drafts[old.id])drafts[old.id].fingerprint=old.fingerprint;}}if(duplicatePolicy==='skip'&&tracks.some(t=>t.fingerprint===fingerprint)){duplicates++;continue;}const t:Track={id:crypto.randomUUID(),name:file.name.replace(/\.[^.]+$/,''),moods:page==='categories'?[scene]:[],tags:[],exclude:[],description:'',gain:.8,intensity:-1,size:file.size,type:file.type,fingerprint};await db.importTrack(t,file);tracks.push(t);selected=t.id;n++;}catch(e){errors.push(file.name+'：'+e.message);}}await send('library');}finally{importReport=`共 ${files.length} 个文件；成功 ${n}，跳过重复 ${duplicates}，失败 ${errors.length}。\n`+errors.join('\n');$('files').value='';busy=false;await reloadTracks();render();modal('音频导入结果',`<pre class="import-report">${esc(importReport)}</pre><p>新曲目请选择适用情绪后保存；完整记录可在曲目库的“上次导入报告”查看。</p>${b('知道了','close','','primary')}`);notice(`已导入 ${n} 首，失败 ${errors.length} 项`);}};
$('backupFile').onchange=async()=>{const file=$('backupFile').files[0];$('backupFile').value='';if(!file)return;if(busy){notice('请等待当前操作完成');return;}busy=true;try{if(file.size>750*1048576)throw Error('备份文件超过 750MB，请使用较小的备份');backupInput=validateBundle(JSON.parse(await file.text()));const duplicate=backupInput.tracks.filter(t=>tracks.some(x=>x.id===t.id||t.fingerprint&&x.fingerprint===t.fingerprint)).length;modal('备份预检',`<p>格式版本 ${backupInput.version} · ${backupInput.tracks.length} 首资料 · ${backupInput.audio.length} 份音频 · ${duplicate} 首重复。</p>${select('重复记录处理','backupMode',[['skip','跳过已有记录'],['copy','导入为独立副本']],'skip')}${b('预览合并结果','confirmBackup','','primary')}`);}catch(e){notice('备份无法导入：'+e.message,8000);}finally{busy=false;}};
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPreview();});window.addEventListener('pagehide',stopPreview);$('dialog').addEventListener('close',()=>{discardAI();drawer=false;if(page==='settings')render();});
window.addEventListener('beforeunload',e=>{const dirty=Object.values(drafts).some(t=>JSON.stringify(t)!==JSON.stringify(tracks.find(x=>x.id===t.id)))||Object.keys(connectionDrafts).some(id=>JSON.stringify(connectionDrafts[id])!==JSON.stringify(c.connections.find(x=>x.id===id)))||Object.keys(modelDrafts).some(id=>JSON.stringify(modelDrafts[id])!==JSON.stringify(c.models.find(x=>x.id===id)));if(Object.entries(moodDrafts).some(([id,d])=>{const m=c.moods.find(x=>x.id===id);return m&&(m.name!==d.name||m.description!==d.description);})||dirty||Object.keys(rawHeaders).length||Object.keys(rawExtra).length||JSON.stringify(taskDraft)!==JSON.stringify({...c.tasks,maxOutput:c.maxOutput||220,maxChars:c.maxChars})||Object.entries(prefs).some(([k,v])=>c[k]!==v)){e.preventDefault();e.returnValue='';}});
async function init(){await send('state');c=upgradeConfig((await chrome.storage.local.get('config')).config);try{connectionId=resolve(c).connection.id;modelId=resolve(c).model.id;}catch{connectionId=c.connections[0]?.id;modelId=c.models.find(m=>m.connectionId===connectionId)?.id||'';}scene=c.moods[0].id;taskDraft={...c.tasks,maxOutput:c.maxOutput||220,maxChars:c.maxChars};prefs={enabled:c.enabled,floating:c.floating,volume:c.volume,fade:c.fade,defaultTrack:c.defaultTrack};await reloadTracks();runtime=await send('state');render();setInterval(async()=>{try{runtime=await send('state');if($('globalPause'))$('globalPause').textContent=runtime.paused?'恢复配乐':'暂停配乐';if($('liveStatus'))$('liveStatus').innerHTML=status();if(['diagnostics','data'].includes(page))void refreshReadiness();updatePreview();}catch{}},1500);}
void init().catch(e=>{$('app').textContent='设置页加载失败：'+e.message;});
function diagnosticPage(){return `<section><div class="main-head"><div><h1>播放</h1><p>为当前故事配乐。</p></div></div><div class="dashboard-grid"><div class="dashboard-left"><section class="surface now-playing"><div class="track-art" aria-hidden="true">${icon('music')}<span>故事的声音</span></div><div class="player-info"><div class="section-heading"><h2>当前配乐</h2><span id="playState" class="small"></span></div><div id="runtimeDetail"></div><div class="row transport">${b(icon('play')+'开始配乐','startMusic','','primary')}${b(icon('next')+'下一首','nextMusic','','outline')}</div><p id="playPosition" class="small">等待播放</p></div></section><div id="judgingStatus" class="judging-status" role="status">判断期间继续播放，相同曲目保持进度。</div><section class="surface candidates-panel"><div class="section-heading"><h2>匹配曲目</h2></div><div id="candidateTracks"></div></section></div><aside class="dashboard-right"><section class="surface atmosphere-panel"><h2>当前氛围</h2><div id="selectionDetail"></div><div class="rule model-summary"><h3>当前判断模型</h3><p>${esc(modelName(c.tasks.scene))}</p><p class="small">AI 判断氛围，本地选择音乐。</p></div></section><section class="surface rules-panel"><h2>播放规则</h2><div class="rule-row"><span>判断期间继续播放</span><strong>自动保持</strong></div><div class="rule-row"><span>相同曲目保持进度</span><strong>自动保持</strong></div></section><p class="small">仅在前台游玩时自动配乐；本页试听单独控制。</p></aside></div><details class="surface connection-panel" id="gameConnections"><summary>游玩页连接与选曲详情</summary><label class="label" for="targetGame">已连接的游玩页</label><select id="targetGame"></select><p class="small">开始配乐会判断当前完整剧情；缓存命中不新增请求。请返回所选游戏页播放。</p><div class="row">${b('固定此游戏','pinGame','','outline')}${b('取消固定','unpinGame','','quiet')}</div><div id="selectionReasons"></div></details></section>`;}
let readinessBusy=false;
async function refreshReadiness(){if(readinessBusy||!($('readyChecks')||$('runtimeDetail')))return;readinessBusy=true;try{readyState=await send('readiness');if(!($('readyChecks')||$('runtimeDetail')))return;if($('readinessSummary'))$('readinessSummary').textContent=readyState.allReady?'运行检查 · 准备就绪':`运行检查 · ${readyState.checks.filter(x=>!x.ok).length} 项待处理`;if($('readyChecks'))$('readyChecks').innerHTML=`<p class="small">版本 ${esc(readyState.version)} · ${readyState.allReady?'基础条件已就绪':'还有准备项未完成'}</p>`+readyState.checks.map(x=>`<div class="check-result"><strong>${esc(x.name)}</strong><span><b>${x.ok?'已就绪':'待处理'}</b> · ${esc(x.detail)}</span></div>`).join('');runtime=await send('state');if(!$('runtimeDetail'))return;$('runtimeDetail').innerHTML=`<h2 class="current-song">${esc(runtime.trackName||'还没有音乐播放')}</h2><p>${esc(runtime.source?`${runtime.source.title} · 第 ${runtime.source.turn} 回合`:'等待前台游玩页面连接')}</p>${runtime.error?`<p class="runtime-error">${esc(runtime.error)}</p>`:''}`;$('playState').textContent=runtime.status||'等待连接';if($('playPosition'))$('playPosition').textContent=runtime.trackId?'已播放 '+formatTime(runtime.position||0)+' · 保持原曲进度':'等待播放';if($('judgingStatus'))$('judgingStatus').textContent=runtime.pending?'正在判断新剧情，当前音乐保持播放。':runtime.error?'判断遇到问题，请检查模型设置；不会自动切换服务。':'判断期间继续播放，相同曲目保持进度。';const old=$('targetGame').value;$('targetGame').innerHTML=opts(readyState.targets.map(t=>[String(t.tabId),`${t.title} · ${t.connected?'已连接':'未连接'} · ${t.turn??'?'} 回合`]),old||String(runtime.pinnedTab||readyState.targets[0]?.tabId||''));const e=runtime.explanation;$('selectionDetail').innerHTML=`<div><h3>当前氛围</h3><strong class="mood-name">${esc(runtime.lockMood?moodName(runtime.lockMood):runtime.decision?moodName(runtime.decision.mood):'尚未判断')}</strong></div><div><p>${esc(e?.summary||'准备好模型与曲库后，在游戏页开始配乐。')}</p><p class="small">${runtime.decision?`强度 ${runtime.decision.intensity} · ${esc(runtime.decision.tags?.join('、')||'无额外标签')} · `:''}${esc(({cache:'复用缓存',model:'模型判断',manual:'手动锁定'})[runtime.resultSource]||'不额外请求 AI')}</p></div>`;const candidates=(e?.reasons||[]).filter(r=>r.score!==null).slice(0,4);const candidateHtml=candidates.length?candidates.map(r=>`<div class="candidate-row"><div><strong>${esc(r.name)}</strong><p class="small">${esc(r.reason)}</p></div><span class="small">${r.id===runtime.trackId?'当前曲目':'可用候选'}</span>${b('试听','listen',`data-id="${esc(r.id)}"`,'outline')}</div>`).join(''):'<p class="candidate-empty">尚无候选音乐。完成一次情绪判断后，这里会列出本地匹配的曲目。</p>';if($('candidateTracks').innerHTML!==candidateHtml)$('candidateTracks').innerHTML=candidateHtml;$('selectionReasons').innerHTML=e?`<p class="small">${e.candidates} 首候选 · ${esc(e.summary)}</p>`:'' ;}catch(e){if($('readyChecks'))$('readyChecks').textContent='无法连接后台：'+e.message;}finally{readinessBusy=false;}}
function dataPage(){return `<section><div class="main-head"><div><h1>偏好与数据</h1><p>调整播放体验，管理本机数据。</p></div>${b('回收与恢复','page','data-id="trash"','outline')}</div><div class="preferences-grid"><section class="surface preferences-panel"><h2>播放偏好</h2><div class="preference-row"><div><h3>总音量</h3><p>控制背景音乐的整体音量。</p></div><div>${field('总音量','volume',prefs.volume,'range','min="0" max="1" step=".01" data-pref="volume"')}<output id="volumeValue">${Math.round(prefs.volume*100)}%</output></div></div><div class="preference-row"><div><h3>曲目切换淡入淡出</h3><p>在不同曲目之间平滑过渡。</p></div><div class="unit-field">${field('过渡秒数','fade',prefs.fade,'number','min="0" max="10" step=".5" data-pref="fade"')}<span aria-hidden="true">秒</span></div></div><div class="preference-row"><div><h3>自动配乐</h3><p>完成新剧情后判断情绪，本地选曲。</p></div><label class="switch"><input id="enabled" type="checkbox" ${prefs.enabled?'checked':''} data-pref="enabled" aria-label="自动配乐"><span></span></label></div><div class="preference-row"><div><h3>游戏内悬浮窗</h3><p>在游戏页面显示小型播放控制窗。</p></div><label class="switch"><input id="floating" type="checkbox" ${prefs.floating?'checked':''} data-pref="floating" aria-label="显示悬浮窗"><span></span></label></div><div class="row preference-actions">${b('重置悬浮窗位置','resetPosition','','outline')}</div><details><summary>无匹配音乐时的处理</summary>${select('无匹配 / 首次判断失败时','defaultTrack',[['','保持静音'],...live().map(t=>[t.id,t.name])],prefs.defaultTrack,'data-pref="defaultTrack"')}</details><div class="row between rule"><p class="small">判断期间继续播放，同曲保持进度。</p>${b('保存偏好','savePrefs','','primary')}</div></section><section class="surface data-panel"><h2>备份与恢复</h2><p>备份音乐与分类，方便迁移与恢复。</p><label class="checkline"><input type="checkbox" id="includeAudio">包含音频副本（最多 512 MB）</label><div class="row">${b('导出备份','exportLibrary','','outline')}${b('导入备份','pickBackup','','outline')}</div><p class="small">密钥与模型连接不包含在曲库备份中。导入前会先预检，不直接覆盖现有音乐。</p>${cachePage()}</section></div><section class="surface data-readiness"><div class="section-heading"><h2 id="readinessSummary">运行检查</h2><div class="row">${b('刷新检查','refreshReady','','quiet')}${b('复制脱敏诊断','copyDiagnostics','','outline')}</div></div><div id="readyChecks"></div><p class="small">音频、密钥和剧情缓存保存在本机。</p></section></section>`;}
function ensureCleanTracks(){if(Object.values(drafts).some(t=>JSON.stringify(t)!==JSON.stringify(tracks.find(x=>x.id===t.id))))throw Error('有未保存的曲目草稿，请先保存或还原再执行批量／恢复操作');}
let duplicatePolicy='skip';
async function advancedAction(action:string,id:string):Promise<boolean>{
 if(action==='showConnections'){$('gameConnections').open=true;$('gameConnections').scrollIntoView?.({block:'nearest',behavior:'smooth'});return true;}
 if(action==='nextMusic'){runtime=await send('control',{command:'next'});await refreshReadiness();return true;}
 if(action==='startMusic'){runtime=await send('control',{command:'start',value:$('targetGame')?.value});notice('已准备开始，请返回所选游戏页；当前锁定保持有效。');await refreshReadiness();return true;}
 if(action==='refreshReady'){await refreshReadiness();return true;}
 if(action==='pinGame'||action==='unpinGame'){const target=action==='pinGame'?$('targetGame').value:null;if(action==='pinGame'&&!target)throw Error('没有可固定的游戏');runtime=await send('control',{command:'pinTab',value:target});await refreshReadiness();return true;}
 if(action==='copyDiagnostics'){const d=await send('diagnostics'),text=JSON.stringify(d,null,2);try{await navigator.clipboard.writeText(text);notice('已复制脱敏诊断，无密钥和剧情全文');}catch{modal('脱敏诊断',area('可选择并复制以下内容','diagnosticText',text,'readonly'));}return true;}
 if(action==='resetPosition'){runtime=await send('control',{command:'floatPosition',value:null});notice('悬浮窗位置已重置');return true;}
 if(action==='deleteModel'||action==='confirmDeleteModel'){const m=c.models.find(x=>x.id===id&&!x.deleted);if(!m)throw Error('模型不存在或已删除');if(c.tasks.scene===id)throw Error('这是当前判断模型，请先在页面顶部选择并保存其他模型，再删除。');if(action==='deleteModel'){modal('删除已配置模型',`<p>将「${esc(m.name||m.model)}」移入已删除模型列表，可以恢复。此服务的地址、密钥与其他模型保持不变。</p><p class="small">此模型未保存的修改将被丢弃，不会调用 AI。</p><div class="row">${b('确认删除','confirmDeleteModel',`data-id="${id}"`,'outline danger')}${b('取消','close','','outline')}</div>`);return true;}await persist({models:c.models.map(x=>x.id===id?{...x,deleted:true,disabled:true}:x)});delete modelDrafts[id];delete rawExtra[id];delete testResults[id];if(taskDraft.scene===id)taskDraft.scene=c.tasks.scene;modelId=c.models.find(x=>!x.deleted)?.id||'';close();render();notice('模型已删除，可从“已删除模型”恢复；服务连接保留。');return true;}
 if(action==='deletedModels'){const deleted=c.models.filter(m=>m.deleted);modal('已删除模型',deleted.length?`<p>恢复后模型保持停用，可编辑并启用；不会自动切换当前模型。</p><div class="stack">${deleted.map(m=>`<div class="row between"><span>${esc(m.name||m.model)}</span>${b('恢复模型','restoreModel',`data-id="${m.id}"`,'outline')}</div>`).join('')}</div>`:'<p>没有已删除的模型。</p>');return true;}
 if(action==='restoreModel'){const m=c.models.find(x=>x.id===id&&x.deleted);if(!m)throw Error('没有找到可恢复的模型');await persist({models:c.models.map(x=>x.id===id?{...x,deleted:false,disabled:true}:x)});modelId=id;close();render();notice('模型已恢复为停用状态；启用后可选择为判断模型。');return true;}
 if(action==='toggleConnection'||action==='toggleModel'){const p=c.connections.find(x=>x.id===connectionId),m=c.models.find(x=>x.id===modelId);if(action==='toggleConnection'){await persist({connections:c.connections.map(x=>x.id===p.id?{...x,disabled:!x.disabled}:x)});delete connectionDrafts[p.id];}else{await persist({models:c.models.map(x=>x.id===m.id?{...x,disabled:!x.disabled}:x)});delete modelDrafts[m.id];}close();render();notice('启用状态已保存；未切换当前判断模型');return true;}
 if(action==='saveCachePolicy'){await persist({cachePolicy:{maxRounds:+$('cacheMax').value,days:+$('cacheDays').value}});notice('缓存保留策略已保存，之后淘汰记录仍可恢复');return true;}
 if(action==='pruneCache'){const r=await send('clearCache',{policy:true});await refreshCache();notice(`已将 ${r.count} 条过期／超量记录移至缓存回收区`);return true;}
 if(action==='selectVisible'){for(const input of document.querySelectorAll<HTMLInputElement>('[data-bulk]'))bulk.add(input.dataset.bulk);render();return true;}
 if(action==='clearBulk'){bulk.clear();render();return true;}
 if(action==='bulkEdit'){ensureCleanTracks();if(!bulk.size)throw Error('请先勾选曲目');modal('批量编辑 '+bulk.size+' 首音乐',`<p>只修改情绪与适用标签，排除标签、说明、音量和强度保持不变。</p>${select('修改方式','batchMode',[['append','追加到已有情绪／标签'],['replace','替换已有情绪／标签']],'append')}${checks('适用情绪','batchMoods',c.moods.filter(m=>!m.disabled).map(m=>[m.id,m.name]),[])}${checks('适用标签','batchTags',c.tags,[])}${b('保存批量修改','saveBulk','','primary')}`);return true;}
 if(action==='saveBulk'){ensureCleanTracks();const moods=[...document.querySelectorAll<HTMLInputElement>('[data-check=batchMoods]:checked')].map(x=>x.value),tags=[...document.querySelectorAll<HTMLInputElement>('[data-check=batchTags]:checked')].map(x=>x.value),mode=$('batchMode').value;if(mode==='replace'&&!moods.length)throw Error('替换时至少选择一个情绪');const changes=batchTracks(tracks,[...bulk],moods,tags,mode);await db.changeLibrary(changes,[],{label:'批量编辑曲目'});drafts={};await reloadTracks();await send('library');close();render();notice(`已更新 ${changes.length} 首，可在数据管理 → 回收与恢复中撤销`);return true;}
 if(action==='manageMood'){ensureCleanTracks();const m=c.moods.find(x=>x.id===scene),affected=tracks.filter(t=>t.moods.includes(scene));modal('管理「'+esc(m.name)+'」',`<p>影响 ${affected.length} 首曲目（含回收站）。停用保留关联，合并将关联改到目标类别并停用原类别；操作可恢复。</p><details><summary>受影响曲目</summary>${affected.map(t=>`<p>${esc(t.name)}</p>`).join('')||'没有关联曲目'}</details>${b(m.disabled?'重新启用类别':'停用类别','toggleMood','','outline')}${select('合并到另一个启用类别','mergeTarget',c.moods.filter(x=>x.id!==scene&&!x.disabled).map(x=>[x.id,x.name]),'')}${b('合并并保留恢复记录','mergeMood','','primary')}`);return true;}
 if(action==='mergeMood'||action==='toggleMood'){ensureCleanTracks();c=upgradeConfig(await send(action,{from:scene,to:$('mergeTarget')?.value}));drafts={};await reloadTracks();close();render();notice('类别与曲目关联已更新，锁定状态已同步，可恢复');return true;}
 if(action==='exportLibrary'){notice('正在生成本地备份，不调用 AI…',30000);const data=await exportLibrary(c,$('includeAudio').checked);download('随境配乐-曲库-'+new Date().toISOString().slice(0,10)+'.omni.json',data);notice('已生成备份，请在浏览器下载记录中确认文件');return true;}
 if(action==='pickBackup'){$('backupFile').click();return true;}
 if(action==='confirmBackup'){ensureCleanTracks();const mode=$('backupMode').value;const plan=planImport(backupInput,c,tracks,mode);modal('确认合并备份',`<p>将新增 ${plan.tracks.length} 首，跳过 ${plan.skipped} 首重复记录；${plan.missing} 首未包含音频。</p><p>原曲目不覆盖；操作保留恢复记录。</p>${b('执行合并','applyBackup',`data-id="${mode}"`,'primary')}`);return true;}
 if(action==='applyBackup'){ensureCleanTracks();const result=await importLibrary(backupInput,c,id==='copy'?'copy':'skip');try{await persist({moods:result.moods,tags:result.tags});}catch(e){await db.restoreLibrary(result.archive);throw e;}drafts={};await reloadTracks();await send('library');close();render();notice(`已导入 ${result.tracks.length} 首，缺失音频 ${result.missing} 首`);backupInput=null;return true;}
 if(action==='libraryHistory'){const archives=await db.libraryArchives();if(!archives.length)throw Error('尚无可恢复的曲库操作');modal('曲库恢复记录',`<p>恢复会还原该批次影响的曲目，覆盖这些曲目后续编辑；当前状态另存为撤销记录。新导入曲目会移入回收站，音频不会删除。</p>${select('选择恢复批次','libraryArchive',archives.map(x=>[x.id,new Date(x.time).toLocaleString()+' · '+x.label+' · '+x.count+' 首']),archives[0].id)}${b('恢复选定批次','restoreLibrary','','primary')}`);return true;}
 if(action==='restoreLibrary'){ensureCleanTracks();c=upgradeConfig(await send('restoreLibrary',{id:$('libraryArchive').value}));drafts={};await reloadTracks();await send('library');close();render();notice('已恢复曲库操作，恢复前状态也已保留');return true;}
 if(action==='pickAudio'){duplicatePolicy=$('duplicates').value;close();$('files').click();return true;}
 return false;
}

function discardAI(){if(aiEditor==='connection'){delete connectionDrafts[connectionId];delete rawHeaders[connectionId];}if(aiEditor==='model'){delete modelDrafts[modelId];delete rawExtra[modelId];}aiEditor='';newEntity=false;}
function refreshAI(){if(aiEditor!=='connection'&&!newEntity){render();return;}const inline=document.querySelector('.model-editor');if(inline)inline.innerHTML='<p>正在编辑，请完成或关闭对话框。</p>';const priorFocus=document.activeElement as HTMLElement;drawer=true;modal(aiEditor==='connection'?(newEntity?'添加服务':'编辑服务'):(newEntity?'添加模型':'编辑模型'),aiEditor==='connection'?connectionForm():modelForm());$('dialog').classList.add('ai-drawer');const next=priorFocus?.id?$(priorFocus.id):null;(next||$('dialog').querySelector('input,select,textarea,button'))?.focus();if(priorFocus?.closest('dialog'))focusReturn=document.querySelector(aiEditor==='connection'?'[data-action=newConnection]':'[data-action=newModel]') as HTMLElement;}

